<div x-show="tab==='kanban'" x-cloak class="max-w-full mx-auto px-4 py-4"><div class="kanban-scroll flex gap-3 overflow-x-auto pb-4" style="min-height:60vh"><?php foreach($estadosKanban as $est):$cards=$kanbanData[$est]??[];$borderCls=$colClasses[$est]??'border-slate-500';?><div class="flex-shrink-0 w-72 bg-slate-800/50 border border-slate-600 rounded-xl p-3 flex flex-col"><div class="text-xs font-semibold uppercase tracking-wider text-slate-200 mb-3 px-1"><?=escHtml($est)?> <span class="text-slate-200">(<?=count($cards)?>)</span></div><div class="space-y-2 flex-1 overflow-y-auto max-h-[55vh]"><?php foreach($cards as $card):$waLink=getWaLink($card['telefono_movil']??'');$hasWa=(int)($card['tiene_whatsapp']??0);$opens=(int)($card['num_opens']??0);$isDup=(int)($card['es_duplicado']??0);$dupId=$card['duplicado_id']??null;$tempBadge=temperaturaBadge($card['estado_lead']??'Sin Contactar',$card['ultimo_contacto']??null);?><div class="bg-slate-700 border-l-4 <?=$borderCls?> rounded-lg p-3 cursor-pointer hover:bg-slate-700/70 transition text-sm" @click="openLead(<?=$card['id']?>)"><div class="font-normal text-slate-200 text-xs mb-1 flex items-center justify-between"><?=escHtml($card['nombre_club'])?><span class="<?=$tempBadge['class']?> text-[11px] font-normal px-1 py-0.5 rounded-full" title="<?=$tempBadge['title']?>"><?=$tempBadge['label']?></span></div><div class="flex items-center gap-2 flex-wrap text-sm text-slate-300"><?php if($card['persona_contacto']):?><span class="text-slate-200"><?=escHtml($card['persona_contacto'])?></span><?php endif;?><?php if($waLink&&$hasWa):?><a href="<?=escHtml($waLink)?>" target="_blank" @click.stop class="text-emerald-400 hover:text-emerald-300 font-normal" title="WhatsApp"><i data-lucide="message-circle" class="w-3 h-3 inline"></i> WA</a><?php endif;?><?php if($opens>0):?><span class="bg-cyan-500/15 text-cyan-400 px-1.5 py-0.5 rounded-full text-xs font-normal"><?=$opens?></span><?php endif;?><?php if($isDup):?><span class="bg-amber-500/15 text-amber-400 px-1.5 py-0.5 rounded-full text-xs font-normal cursor-pointer" @click.stop="openMerge(<?=$dupId?>,<?=$card['id']?>)">DUPLICADO</span><?php endif;?></div></div><?php endforeach;?></div></div><?php endforeach;?></div></div>

