<div x-show="nm" @click.self="nm=false" class="fixed inset-0 z-50 flex items-center justify-center bg-black/60" x-cloak x-transition>
<div class="bg-slate-800 border border-slate-600 rounded-2xl w-full max-w-lg m-4"><div class="px-5 py-3 border-b border-slate-600 flex items-center justify-between"><h5 class="text-sm font-semibold text-emerald-400">+ Añadir Nuevo Club / Lead</h5><button @click="nm=false" class="text-slate-300 hover:text-slate-300" title="Cerrar"><i data-lucide="x" class="w-5 h-5"></i></button></div>
<div class="p-5 space-y-3"><div class="grid grid-cols-2 gap-3"><div><label class="text-sm text-slate-300 uppercase tracking-wider">Nombre del Club *</label><input type="text" x-model="nl.nombre_club" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-emerald-500/50"></div><div><label class="text-sm text-slate-300 uppercase tracking-wider">Email de Contacto *</label><input type="email" x-model="nl.email" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-emerald-500/50"></div></div><div class="grid grid-cols-2 gap-3"><div><label class="text-sm text-slate-300 uppercase tracking-wider">Teléfono</label><input type="text" x-model="nl.telefono_movil" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div><div><label class="text-sm text-slate-300 uppercase tracking-wider">Federación / Región</label><input type="text" x-model="nl.federacion" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div></div><div class="grid grid-cols-2 gap-3"><div><label class="text-sm text-slate-300 uppercase tracking-wider">Persona de Contacto</label><input type="text" x-model="nl.persona_contacto" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div><div><label class="text-sm text-slate-300 uppercase tracking-wider">Cargo</label><input type="text" x-model="nl.cargo_contacto" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div></div><div><label class="text-sm text-slate-300 uppercase tracking-wider">Estado Inicial</label><select x-model="nl.estado_lead" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"><option value="Sin Contactar">Sin Contactar</option><option value="Email Enviado / En Secuencia">Email Enviado / En Secuencia</option><option value="En Conversacion / WhatsApp">En Conversación / WhatsApp</option></select></div><div class="flex gap-2 pt-2"><button @click="nm=false" class="flex-1 px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-xs text-slate-200 hover:bg-slate-700 transition">Cancelar</button><button @click="guardarNuevoLead()" class="flex-1 px-4 py-2 bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 rounded-lg text-xs font-normal hover:bg-emerald-500/30 transition">💾 Guardar Club</button></div></div></div></div>

<!-- MODAL SMTP -->
<div x-show="sm" @click.self="sm=false" class="fixed inset-0 z-50 flex items-center justify-center bg-black/60" x-cloak x-transition>
<div class="bg-slate-800 border border-slate-600 rounded-2xl w-full max-w-md m-4"><div class="px-5 py-3 border-b border-slate-600 flex items-center justify-between"><h5 class="text-sm font-semibold text-slate-200" x-text="se?'Editar Cuenta SMTP':'Nueva Cuenta SMTP'"></h5><button @click="sm=false" class="text-slate-300 hover:text-slate-300" title="Cerrar"><i data-lucide="x" class="w-5 h-5"></i></button></div>
<div class="p-5 space-y-3"><div><label class="text-sm text-slate-300 uppercase tracking-wider">Email Emisor</label><input type="email" x-model="sf.email" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div><div class="grid grid-cols-4 gap-2"><div class="col-span-3"><label class="text-sm text-slate-300 uppercase tracking-wider">Host</label><input type="text" x-model="sf.host" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div><div><label class="text-sm text-slate-300 uppercase tracking-wider">Puerto</label><input type="number" x-model="sf.puerto" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div></div><div><label class="text-sm text-slate-300 uppercase tracking-wider">Usuario</label><input type="text" x-model="sf.usuario" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div><div><label class="text-sm text-slate-300 uppercase tracking-wider">Password</label><input type="password" x-model="sf.password" placeholder="Dejar vacio para no cambiar" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div><div class="grid grid-cols-2 gap-2"><div><label class="text-sm text-slate-300 uppercase tracking-wider">Seguridad</label><select x-model="sf.seguridad" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"><option value="ssl">SSL</option><option value="tls">TLS</option></select></div><div><label class="text-sm text-slate-300 uppercase tracking-wider">Limite Diario</label><input type="number" x-model="sf.limite_diario" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-1.5 text-xs text-slate-300 focus:outline-none focus:border-amber-500/50"></div></div><div class="flex gap-2 pt-2"><button @click="sm=false" class="flex-1 px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-xs text-slate-200 hover:bg-slate-700 transition">Cancelar</button><button @click="saveSmtp()" class="flex-1 px-4 py-2 bg-blue-500/20 text-blue-400 border border-blue-500/30 rounded-lg text-xs font-normal hover:bg-blue-500/30 transition">Guardar</button></div></div></div></div>

<script>function app(){return{
tab:'kanban',killSwitch:<?=$motorActivo?'true':'false'?>,modeTest:<?=$modoPruebas?'true':'false'?>,
lm:false,mm:false,sm:false,ln:'',mn:true,mk:0,md:0,tlNota:'',waTplSel:'',
ld:{},mf:[],mha:'',mhb:'',
se:0,sf:{email:'',host:'mail.getfutprotec.com',puerto:465,usuario:'',password:'',seguridad:'ssl',limite_diario:50},
gs:'',ge:'',gf:'',gt:'',gp:1,gpp:50,gsc:'nombre_club',gso:'ASC',
// Editor de plantillas
selectedTplId:0,tplNombre:'',tplAsuntoVal:'',tplCuerpoVal:'',tplTipoVal:'html',tplCatVal:'prospeccion',tplFiltroCat:'',plantillasList:[],editMode:true,
waPlantillas:[],nm:false,nl:{nombre_club:'',email:'',telefono_movil:'',persona_contacto:'',cargo_contacto:'',federacion:'',estado_lead:'Sin Contactar'},
// Lanzadera Outbound
lzMotorActivo:false,lzDelay:3,lzInterval:null,lzLogs:[],lzLogCount:0,lzCola:[],lzSmtpData:[],
get waLink(){const m=this.ld.telefono_movil||'';const n=m.split(',').map(s=>s.trim()).filter(s=>/^[67]\d{8}$/.test(s));return n.length>0?'https://wa.me/34'+n[0]:'';},
async boot(){window.__app=this;lucide.createIcons();await this.loadGestor();await this.loadSmtp();await this.loadWaPlantillas()},
async toggleWa(){this.ld.tiene_whatsapp=!this.ld.tiene_whatsapp;await this.saveF('tiene_whatsapp',this.ld.tiene_whatsapp?1:0)},
async toggleKS(){this.killSwitch=!this.killSwitch;const f=new FormData();f.append('action','update_config');f.append('key','motor_estado');f.append('value',this.killSwitch?'activo':'pausado');await fetch('',{method:'POST',body:f})},
async toggleModo(){this.modeTest=!this.modeTest;const f=new FormData();f.append('action','update_config');f.append('key','modo_entorno');f.append('value',this.modeTest?'test':'produccion');await fetch('',{method:'POST',body:f})},

async openLead(id){const r=await fetch('?action=get_lead&id='+id);this.ld=await r.json();this.ln='';this.ld.tiene_whatsapp=!!(+this.ld.tiene_whatsapp);this.lm=true;await this.loadTimeline(id);setTimeout(()=>lucide.createIcons(),100)},
async saveF(field,value){if(!this.ld.id)return;const f=new FormData();f.append('action','update_lead');f.append('id',this.ld.id);f.append('field',field);f.append('value',value);await fetch('',{method:'POST',body:f})},
async addNota(){if(!this.ln.trim())return;await this.saveF('observaciones',this.ln);const r=await fetch('?action=get_lead&id='+this.ld.id);this.ld=await r.json();this.ln=''},

async loadTimeline(lid){const r=await fetch('api_leads.php?action=get_timeline&lead_id='+lid);const j=await r.json();const el=document.getElementById('timelineBody');if(!el)return;if(!j.ok||!j.eventos.length){el.innerHTML='<span class="text-xs text-slate-200">Sin eventos registrados</span>';return}let h='';const icons={email_enviado:'✉️',email_abierto:'👁️',nota_manual:'📝',respuesta_recibida:'📩'};j.eventos.forEach(e=>{const ico=icons[e.tipo_evento]||'📌';const fe=new Date(e.fecha+'Z');const tf=fe.toLocaleString('es-ES',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});h+='<div class="flex items-start gap-2 text-xs py-1 border-b border-slate-600/30"><span class="text-xs">'+ico+'</span><div><span class="text-slate-200 font-normal">'+e.tipo_evento.replace(/_/g,' ')+'</span><span class="text-slate-200 ml-2">'+tf+'</span><div class="text-slate-300">'+this.esc(e.detalles||'')+'</div></div></div>'});el.innerHTML=h},
async addTimelineNota(){const dt=this.tlNota.trim();if(!dt||!this.ld.id)return;const f=new FormData();f.append('action','add_nota_timeline');f.append('lead_id',this.ld.id);f.append('detalles',dt);const r=await fetch('api_leads.php',{method:'POST',body:f});const j=await r.json();if(j.ok){this.tlNota='';await this.loadTimeline(this.ld.id)}},

async loadWaPlantillas(){const r=await fetch('api_leads.php?action=get_plantillas_wa');const j=await r.json();if(j.ok)this.waPlantillas=j.plantillas||[]},
async abrirWaTpl(){if(!this.waTplSel||!this.waLink)return;const t=this.waPlantillas.find(x=>x.id==this.waTplSel);if(!t)return;let msg=t.cuerpo.replace(/\{\{CLUB\}\}/g,this.ld.nombre_club||'Club').replace(/\{\{CONTACTO\}\}/g,this.ld.persona_contacto||'responsable').replace(/\{\{FEDERACION\}\}/g,this.ld.federacion||'');window.open(this.waLink+'?text='+encodeURIComponent(msg),'_blank')},

async openMerge(k,d){this.mk=k;this.md=d;const[r1,r2]=await Promise.all([fetch('?action=get_lead&id='+k).then(r=>r.json()),fetch('?action=get_lead&id='+d).then(r=>r.json())]);const a=r1,b=r2;if(!a||!b)return;this.mha=this.fr('Club',a.nombre_club)+this.fr('Email',a.email)+this.fr('Fed',a.federacion||'')+this.fr('Contacto',a.persona_contacto)+this.fr('Movil',a.telefono_movil)+this.fr('Fijo',a.telefono_fijo)+this.fr('Estado',a.estado_lead)+'<div class="mt-1"><strong class="text-slate-300 text-sm">Notas:</strong><br>'+this.esc(a.observaciones||'(sin notas)')+'</div>';this.mhb=this.fr('Club',b.nombre_club)+this.fr('Email',b.email)+this.fr('Fed',b.federacion||'')+this.fr('Contacto',b.persona_contacto)+this.fr('Movil',b.telefono_movil)+this.fr('Fijo',b.telefono_fijo)+this.fr('Estado',b.estado_lead)+'<div class="mt-1"><strong class="text-slate-300 text-sm">Notas:</strong><br>'+this.esc(b.observaciones||'(sin notas)')+'</div>';this.mf=[{name:'nombre',label:'Nombre',vA:a.nombre_club,vB:b.nombre_club,cA:true},{name:'contacto',label:'Contacto',vA:a.persona_contacto,vB:b.persona_contacto,cA:!!a.persona_contacto},{name:'movil',label:'Movil',vA:a.telefono_movil,vB:b.telefono_movil,cA:!!a.telefono_movil},{name:'fijo',label:'Fijo',vA:a.telefono_fijo,vB:b.telefono_fijo,cA:!!a.telefono_fijo},{name:'estado',label:'Estado',vA:a.estado_lead,vB:b.estado_lead,cA:true}];this.mm=true;this.mn=true;setTimeout(()=>lucide.createIcons(),100)},
fr(label,val){return'<div><strong class="text-slate-300 text-sm">'+label+':</strong> '+this.esc(val||'-')+'</div>'},
async doMerge(){const fm={nombre:'nombre_club',contacto:'persona_contacto',movil:'telefono_movil',fijo:'telefono_fijo',estado:'estado_lead'};for(const f of this.mf){const s=document.querySelector('input[name="mg_'+f.name+'"]:checked');if(s&&s.value==='B'){const fd=new FormData();fd.append('action','update_lead');fd.append('id',this.mk);fd.append('field',fm[f.name]);const bL=await fetch('?action=get_lead&id='+this.md).then(r=>r.json());fd.append('value',bL[fm[f.name]]||'');await fetch('',{method:'POST',body:fd})}}const fd=new FormData();fd.append('action','merge_leads');fd.append('keep_id',this.mk);fd.append('dup_id',this.md);fd.append('merge_notes',this.mn?'1':'0');const r=await fetch('api_leads.php',{method:'POST',body:fd});const j=await r.json();if(j.ok){this.mm=false;location.reload()}else{alert('Error: '+(j.error||'Desconocido'))}},

async scanDups(){const r=await fetch('api_leads.php?action=scan_duplicates');const j=await r.json();if(j.ok){alert('Escaneo: '+j.dups+' duplicados en '+j.total+' clubes.');location.reload()}else{alert('Error: '+(j.error||'Desconocido'))}},

async loadGestor(){const A=window.__app||this;const p=new URLSearchParams({action:'get_leads_table',page:A.gp,per_page:A.gpp,sort:A.gsc,order:A.gso,search:A.gs,estado:A.ge,federacion:A.gf});const r=await fetch('api_leads.php?'+p.toString());const j=await r.json();if(!j.ok)return;A.gt=j.total+' resultados';let h='';j.data.forEach(l=>{const tb=tempCalc(l.estado_lead);h+='<tr class="border-b border-slate-600/50 hover:bg-slate-700/30 transition"><td class="px-3 py-2"><span class="font-medium text-slate-300">'+A.esc(l.nombre_club)+'</span><span class="'+tb.cls+' text-[11px] font-normal px-1 py-0.5 rounded-full ml-1" title="'+tb.title+'">'+tb.label+'</span>'+(l.es_duplicado==1?' <span class="bg-amber-500/15 text-amber-400 px-1.5 py-0.5 rounded-full text-xs font-normal cursor-pointer" onclick="window.__app.openMerge('+l.duplicado_id+','+l.id+')" title="Fusionar duplicado">⚠️ DUPLICADO</span>':'')+'</td><td class="px-3 py-2 hidden md:table-cell"><code class="text-sm text-slate-300">'+A.esc(l.email)+'</code></td><td class="px-3 py-2 hidden md:table-cell text-sm text-slate-200 font-mono">'+A.esc(l.telefono_movil||'-')+'</td><td class="px-3 py-2 text-sm text-slate-200">'+A.esc(l.estado_lead)+'</td><td class="px-3 py-2 hidden lg:table-cell text-sm text-slate-200">'+A.esc(l.federacion||'')+'</td><td class="px-3 py-2 text-right"><button class="px-2 py-1 bg-slate-700 border border-slate-600 rounded text-sm text-slate-200 hover:text-slate-100 hover:border-slate-600 transition" onclick="window.__app.openLead('+l.id+')" title="Abrir ficha del club">Ficha</button></td></tr>'});document.getElementById('gestorBody').innerHTML=h||'<tr><td colspan="6" class="px-3 py-8 text-center text-slate-200">Sin resultados</td></tr>';let pg='';const tp=j.total_pages;const cp=A.gp;let s=Math.max(1,cp-2);let e=Math.min(tp,cp+2);if(s>1){pg+=bpg(1);if(s>2)pg+='<span class="px-1 text-slate-200">…</span>'}for(let i=s;i<=e;i++)pg+=bpg(i);if(e<tp){if(e<tp-1)pg+='<span class="px-1 text-slate-200">…</span>';pg+=bpg(tp)}document.getElementById('gestorP').innerHTML=pg;
function bpg(n){return'<button class="px-2 py-0.5 text-sm rounded border '+(n===A.gp?'bg-slate-700 border-slate-600 text-slate-200':'border-slate-600 text-slate-300 hover:text-slate-300')+'" onclick="window.__app.gp='+n+';window.__app.loadGestor()" title="Ir a pagina '+n+'">'+n+'</button>'}},
gSort(col){if(this.gsc===col)this.gso=this.gso==='ASC'?'DESC':'ASC';else{this.gsc=col;this.gso='ASC'}this.gp=1;this.loadGestor()},

// ─── Editor de Plantillas CRUD ───
async loadPlantillas(){const p=this.tplFiltroCat?'&categoria='+encodeURIComponent(this.tplFiltroCat):'';const r=await fetch('api_leads.php?action=get_plantillas'+p);const j=await r.json();if(j.ok)this.plantillasList=j.plantillas||[]},
async cargarTpl(){const id=this.selectedTplId;if(!id||id==0){this.nuevaPlantilla();return}const t=this.plantillasList.find(x=>x.id==id);if(!t)return;this.tplNombre=t.nombre;this.tplAsuntoVal=t.asunto||'';this.tplCuerpoVal=t.cuerpo||'';this.tplTipoVal=t.tipo||'html';this.tplCatVal=t.categoria||'prospeccion';this.editMode=true},
nuevaPlantilla(){this.selectedTplId=0;this.tplNombre='';this.tplAsuntoVal='';this.tplCuerpoVal='';this.tplTipoVal='html';this.tplCatVal='prospeccion';this.editMode=true},
async saveTpl(){const f=new FormData();f.append('action','save_plantilla');if(this.selectedTplId>0)f.append('id',this.selectedTplId);f.append('nombre',this.tplNombre||'Sin nombre');f.append('asunto',this.tplAsuntoVal);f.append('cuerpo',this.tplCuerpoVal);f.append('tipo',this.tplTipoVal);f.append('categoria',this.tplCatVal);const r=await fetch('api_leads.php',{method:'POST',body:f});const j=await r.json();if(j.ok){this.selectedTplId=j.id;await this.loadPlantillas();alert('Plantilla guardada (ID '+j.id+')')}else{alert('Error: '+(j.error||'Desconocido'))}},
async delPlantilla(){const id=this.selectedTplId;if(id<=0)return;if(!confirm('Eliminar esta plantilla?'))return;const f=new FormData();f.append('action','delete_plantilla');f.append('id',id);const r=await fetch('api_leads.php',{method:'POST',body:f});const j=await r.json();if(j.ok){this.nuevaPlantilla();await this.loadPlantillas()}else{alert('Error: '+(j.error||'Desconocido'))}},
async previewTpl(){const ci=document.getElementById('previewClub').value;if(!ci){alert('Selecciona un club');return}const r=await fetch('?action=preview_template&template_id='+(this.selectedTplId||1)+'&club_id='+ci);const j=await r.json();if(!j.ok){alert('Error: '+(j.error||'Desconocido'));return}const iframe=document.getElementById('previewIframe');const textoDiv=document.getElementById('previewTextoPlano');if(this.tplTipoVal==='html'){if(iframe)iframe.srcdoc=j.cuerpo_html}else{if(textoDiv){textoDiv.style.display='block';textoDiv.textContent=j.cuerpo_html;if(iframe)iframe.style.display='none'}}},

async loadSmtp(){const A=window.__app||this;const r=await fetch('api_smtp.php?action=get_accounts');const j=await r.json();if(!j.ok)return;let h='';j.accounts.forEach(a=>{const testBtn='<button class="px-2 py-1 bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 rounded text-sm hover:bg-cyan-500/20 transition relative" onclick="window.__app.testSmtp('+a.id+',this)" title="Test conexion SMTP"><i data-lucide="zap" class="w-3 h-3"></i></button>';h+='<tr class="border-b border-slate-600/50 hover:bg-slate-700/30 transition"><td class="px-3 py-2"><code class="text-sm text-slate-300">'+A.esc(a.email)+'</code></td><td class="px-3 py-2 hidden sm:table-cell text-sm text-slate-300">'+A.esc(a.host)+':'+a.puerto+'</td><td class="px-3 py-2 text-center text-sm"><span class="text-slate-300 font-normal">'+a.enviados_hoy+'</span><span class="text-slate-200"> / '+a.limite_diario+'</span></td><td class="px-3 py-2 text-center">'+(a.activa==1?'<span class="bg-emerald-500/15 text-emerald-400 px-1.5 py-0.5 rounded-full text-xs font-normal">ON</span>':'<span class="bg-slate-700 text-slate-300 px-1.5 py-0.5 rounded-full text-xs font-normal">OFF</span>')+' '+(a.ultimo_error?'<span class="bg-rose-500/15 text-rose-400 px-1.5 py-0.5 rounded-full text-xs font-normal cursor-help" title="'+A.esc(a.ultimo_error)+'">!</span>':'<span class="bg-emerald-500/15 text-emerald-400 px-1.5 py-0.5 rounded-full text-xs font-normal">OK</span>')+'</td><td class="px-3 py-2 text-right"><div class="flex gap-1 justify-end">'+testBtn+'<button class="px-2 py-1 bg-amber-500/10 text-amber-400 border border-amber-500/20 rounded text-sm hover:bg-amber-500/20 transition" onclick="window.__app.toggleSmtp('+a.id+')" title="Activar/Desactivar cuenta"><i data-lucide="power" class="w-3 h-3"></i></button><button class="px-2 py-1 bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded text-sm hover:bg-blue-500/20 transition" onclick="window.__app.openSmtp('+a.id+')" title="Editar cuenta SMTP"><i data-lucide="pencil" class="w-3 h-3"></i></button><button class="px-2 py-1 bg-rose-500/10 text-rose-400 border border-rose-500/20 rounded text-sm hover:bg-rose-500/20 transition" onclick="window.__app.deleteSmtp('+a.id+')" title="Eliminar cuenta SMTP"><i data-lucide="trash-2" class="w-3 h-3"></i></button></div></td></tr>'});document.getElementById('smtpBody').innerHTML=h||'<tr><td colspan="5" class="px-3 py-8 text-center text-slate-200">Sin cuentas</td></tr>';setTimeout(()=>lucide.createIcons(),50)},
async openSmtp(id){this.se=id;if(id>0){const r=await fetch('api_smtp.php?action=get_accounts');const j=await r.json();const a=j.accounts.find(x=>x.id==id);if(a){this.sf={email:a.email,host:a.host,puerto:a.puerto,usuario:a.usuario,password:a.password,seguridad:a.seguridad,limite_diario:a.limite_diario}}}else{this.sf={email:'',host:'mail.getfutprotec.com',puerto:465,usuario:'',password:'',seguridad:'ssl',limite_diario:50}}this.sm=true;setTimeout(()=>lucide.createIcons(),100)},
async saveSmtp(){const f=new FormData();f.append('action','save_account');if(this.se>0)f.append('id',this.se);f.append('email',this.sf.email);f.append('host',this.sf.host);f.append('puerto',this.sf.puerto);f.append('usuario',this.sf.usuario);f.append('password',this.sf.password);f.append('seguridad',this.sf.seguridad);f.append('limite_diario',this.sf.limite_diario);const r=await fetch('api_smtp.php',{method:'POST',body:f});const j=await r.json();if(j.ok){this.sm=false;this.loadSmtp()}else{alert('Error: '+(j.error||'Desconocido'))}},
async toggleSmtp(id){const f=new FormData();f.append('action','toggle_account');f.append('id',id);await fetch('api_smtp.php',{method:'POST',body:f});this.loadSmtp()},
async deleteSmtp(id){if(!confirm('Eliminar esta cuenta SMTP?'))return;const f=new FormData();f.append('action','delete_account');f.append('id',id);const r=await fetch('api_smtp.php',{method:'POST',body:f});const j=await r.json();if(j.ok)this.loadSmtp();else alert('Error: '+(j.error||'Desconocido'))},
async testSmtp(id,btn){if(btn){btn.disabled=true;const orig=btn.innerHTML;btn.innerHTML='<span class="w-3 h-3 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin inline-block"></span>'}const f=new FormData();f.append('action','test_smtp');f.append('id',id);const r=await fetch('api_smtp.php',{method:'POST',body:f});const j=await r.json();const ok=j.status==='success';alert((ok?'CONEXION EXITOSA: ':'ERROR: ')+j.message);if(btn){btn.disabled=false;btn.innerHTML=orig}this.loadSmtp()},

// ─── Lanzadera Outbound ───
cargarLanzaderaData(){const A=window.__app||this;A.bootLanzadera()},
async bootLanzadera(){window.__app=this;this.lzMotorActivo=<?=$motorActivo?'true':'false'?>;this.lzDelay=parseInt('<?=($config['delay_envio']??'3')?>')||3;await Promise.all([this.loadLanzaderaCola(),this.loadLanzaderaSmtp()]);this.lzLog('🚀 Panel Lanzadera cargado. Motor: '+(this.lzMotorActivo?'ACTIVO':'PAUSADO')+', Delay: '+this.lzDelay+'s');lucide.createIcons();if(this.lzMotorActivo){this.lzPollInterval=setInterval(()=>{this.cargarLanzaderaData()},15000)}},
lzLog(msg){const ts=new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',second:'2-digit'});const entry='['+ts+'] '+msg;this.lzLogs.push(entry);if(this.lzLogs.length>200)this.lzLogs.shift();this.lzLogCount=this.lzLogs.length;const el=document.getElementById('console-log-outbound');if(el){el.innerHTML=this.lzLogs.map(s=>'<div>'+this.esc(s)+'</div>').join('');el.scrollTop=el.scrollHeight}},
async lzToggleMotor(){this.lzMotorActivo=!this.lzMotorActivo;const f=new FormData();f.append('action','update_config');f.append('key','motor_estado');f.append('value',this.lzMotorActivo?'activo':'pausado');await fetch('',{method:'POST',body:f});this.lzLog(this.lzMotorActivo?'▶️ Motor ACTIVADO manualmente':'⏸️ Motor PAUSADO manualmente');if(this.lzMotorActivo){this.lzPollInterval=setInterval(()=>{this.cargarLanzaderaData()},15000)}else{if(this.lzPollInterval){clearInterval(this.lzPollInterval);this.lzPollInterval=null}}await this.loadLanzaderaCola()},
async lzSaveDelay(){const f=new FormData();f.append('action','update_config');f.append('key','delay_envio');f.append('value',String(this.lzDelay));await fetch('',{method:'POST',body:f});this.lzLog('⏱️ Delay actualizado a '+this.lzDelay+'s')},
async loadLanzaderaCola(){try{const r=await fetch('api_leads.php?action=get_leads_table&per_page=10&sort=creado_el&order=DESC&estado=Sin+Contactar');const j=await r.json();if(!j.ok)return;this.lzCola=j.data||[];const el=document.getElementById('lzColaBody');if(!el)return;if(!this.lzCola.length){el.innerHTML='<tr><td colspan="4" class="px-2 py-6 text-center text-slate-200">✅ No hay clubes pendientes de primer contacto.</td></tr>';return}const cuentas=this.lzSmtpData||[];let h='';this.lzCola.forEach((c,i)=>{const smtpAsignada=cuentas.length>0?cuentas[i%cuentas.length]:null;const smtpLabel=smtpAsignada?(smtpAsignada.email.split('@')[0]+' ('+smtpAsignada.enviados_hoy+'/'+smtpAsignada.limite_diario+')'):'Sin SMTP';h+='<tr class="border-b border-slate-600/50 hover:bg-slate-700/30 transition"><td class="px-2 py-1.5 text-slate-200 font-mono">'+(i+1)+'</td><td class="px-2 py-1.5"><span class="text-slate-300 font-normal text-sm">'+this.esc(c.nombre_club)+'</span></td><td class="px-2 py-1.5"><code class="text-xs text-slate-300">'+this.esc(c.email)+'</code></td><td class="px-2 py-1.5"><span class="text-[11px] text-slate-200">'+this.esc(smtpLabel)+'</span></td></tr>'});el.innerHTML=h;this.lzLog('📋 Cola actualizada: '+this.lzCola.length+' clubes pendientes (Sin Contactar)')}catch(e){this.lzLog('❌ Error al cargar cola: '+e.message)}},
async loadLanzaderaSmtp(){try{const r=await fetch('api_smtp.php?action=get_accounts');const j=await r.json();if(!j.ok)return;this.lzSmtpData=j.accounts||[];const el=document.getElementById('grid-cuentas-smtp');if(!el)return;if(!this.lzSmtpData.length){el.innerHTML='<div class="text-sm text-slate-200 text-center py-4 col-span-full">Sin cuentas SMTP configuradas</div>';return}let h='';this.lzSmtpData.forEach(a=>{const pct=Math.min(100,Math.round((a.enviados_hoy/Math.max(1,a.limite_diario))*100));const barColor=pct>=90?'bg-rose-500':pct>=70?'bg-amber-500':'bg-emerald-500';const statusColor=a.activa==1?'text-emerald-400':'text-slate-200';const statusLabel=a.activa==1?'● Activa':'○ Inactiva';const errLabel=a.ultimo_error?'⚠️ Error':'✅ OK';h+='<div class="bg-slate-700/50 border border-slate-600/50 rounded-lg px-3 py-2 text-xs"><div class="flex items-center justify-between mb-1"><code class="text-slate-300 truncate max-w-[140px]" title="'+this.esc(a.email)+'">'+this.esc(a.email.split('@')[0])+'</code><span class="font-mono font-normal '+(pct>=90?'text-rose-400':pct>=70?'text-amber-400':'text-emerald-400')+'">'+a.enviados_hoy+'/'+a.limite_diario+'</span></div><div class="w-full bg-slate-700 rounded-full h-1.5"><div class="'+barColor+' h-1.5 rounded-full" style="width:'+pct+'%"></div></div><div class="flex items-center justify-between mt-1"><span class="'+statusColor+'">'+statusLabel+'</span><span class="text-slate-200">'+errLabel+'</span></div></div>'});el.innerHTML=h;this.lzLog('📊 Grid SMTP actualizado: '+this.lzSmtpData.length+' cuentas')}catch(e){this.lzLog('❌ Error al cargar cuentas SMTP: '+e.message)}},
async guardarNuevoLead(){const A=this;if(!A.nl.nombre_club.trim()||!A.nl.email.trim()){alert("Nombre y Email son obligatorios");return}const email=A.nl.email.trim();const vr=await fetch("api_leads.php?action=validate_email&email="+encodeURIComponent(email));const vj=await vr.json();if(!vj.valid){let motivo="";if(vj.reason==="syntax_invalid")motivo="Sintaxis de email inv\u00e1lida";else if(vj.reason==="no_mx_record")motivo="El dominio "+vj.domain+" no tiene registros MX (no recibe correos)";else motivo="Email no v\u00e1lido: "+vj.reason;const archivar=confirm(motivo+"\n\n\u00bfDeseas guardarlo como \"Email Inválido\" para revisarlo m\u00e1s tarde?");if(!archivar)return;A.nl.estado_lead="Email Inválido"}const f=new FormData();f.append("action","save_nuevo_lead");f.append("nombre_club",A.nl.nombre_club);f.append("email",email);f.append("telefono_movil",A.nl.telefono_movil);f.append("persona_contacto",A.nl.persona_contacto);f.append("cargo_contacto",A.nl.cargo_contacto);f.append("federacion",A.nl.federacion);f.append("estado_lead",A.nl.estado_lead);const r=await fetch("api_leads.php",{method:"POST",body:f});const j=await r.json();if(j.ok){const wasArchived=A.nl.estado_lead==="Email Inválido";A.nm=false;A.nl={nombre_club:"",email:"",telefono_movil:"",persona_contacto:"",cargo_contacto:"",federacion:"",estado_lead:"Sin Contactar"};A.loadGestor();alert("Club a\u00f1adido correctamente (ID #"+j.id+")"+(wasArchived?" en estado Email Inválido":""))}else{alert("Error: "+(j.error||"Desconocido"))}},
esc(s){const d=document.createElement('div');d.textContent=s||'';return d.innerHTML}}}
function toggleMotor(){const A=window.__app;if(A)A.lzToggleMotor()}
function cargarLanzaderaDataGlobal(){const A=window.__app;if(A)A.cargarLanzaderaData()}
function tempCalc(estado){if(estado==='Sin Contactar')return{cls:'bg-slate-600/20 text-slate-200',label:'Sin contacto',title:'Nunca contactado'};if(estado.includes('Cerrado Ganado'))return{cls:'bg-emerald-500/15 text-emerald-400',label:'Ganado',title:'Cliente ganado'};if(estado.includes('Cerrado Perdido'))return{cls:'bg-rose-500/15 text-rose-400',label:'Perdido',title:'Cliente perdido'};if(estado.includes('Enviado')||estado.includes('Secuencia'))return{cls:'bg-amber-500/15 text-amber-400',label:'En secuencia',title:'Email enviado, sin abrir'};if(estado.includes('Abrio')||estado.includes('Impactado'))return{cls:'bg-cyan-500/15 text-cyan-400',label:'Abierto',title:'Email abierto'};if(estado.includes('Conversacion')||estado.includes('WhatsApp'))return{cls:'bg-emerald-500/15 text-emerald-400',label:'Conversando',title:'En conversacion activa'};if(estado.includes('Muestra')||estado.includes('Propuesta'))return{cls:'bg-purple-500/15 text-purple-400',label:'Propuesta',title:'Propuesta enviada'};return{cls:'bg-slate-600/20 text-slate-200',label:estado,title:estado}}
</script></body></html>
<?php function temperaturaBadge(string $estado,?string $ultimo):array{$cls='bg-slate-600/20 text-slate-200';$label='';$title='';if($estado==='Sin Contactar'){$label='Sin contacto';$title='Nunca contactado';}elseif(str_contains($estado,'Cerrado Ganado')){$cls='bg-emerald-500/15 text-emerald-400';$label='Ganado';$title='Cliente ganado';}elseif(str_contains($estado,'Cerrado Perdido')){$cls='bg-rose-500/15 text-rose-400';$label='Perdido';$title='Cliente perdido';}elseif(str_contains($estado,'Enviado')||str_contains($estado,'Secuencia')){$cls='bg-amber-500/15 text-amber-400';$label='En secuencia';$title='Email enviado, sin abrir';}elseif(str_contains($estado,'Abrio')||str_contains($estado,'Impactado')){$cls='bg-cyan-500/15 text-cyan-400';$label='Abierto';$title='Email abierto';}elseif(str_contains($estado,'Conversacion')||str_contains($estado,'WhatsApp')){$cls='bg-emerald-500/15 text-emerald-400';$label='Conversando';$title='En conversacion activa';}elseif(str_contains($estado,'Muestra')||str_contains($estado,'Propuesta')){$cls='bg-purple-500/15 text-purple-400';$label='Propuesta';$title='Propuesta enviada';}else{$label=$estado;$title=$estado;}return['class'=>$cls,'label'=>$label,'title'=>$title];}
function showLoginForm(string $error=''):void{?><!DOCTYPE html><html lang="es" class="dark"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>FutProtec — Acceso Panel</title><script src="https://cdn.tailwindcss.com"></script><script>tailwind.config={darkMode:'class'}</script><style>body{font-family:'Inter',system-ui,sans-serif}</style></head><body class="bg-slate-950 min-h-screen flex items-center justify-center"><div class="bg-slate-800 border border-slate-600 rounded-2xl p-8 w-full max-w-sm shadow-2xl"><div class="text-center mb-6"><div class="text-2xl font-bold text-amber-400">FutProtec</div><p class="text-slate-300 text-xs mt-1">Panel CRM Kanban v2.0</p></div><?php if($error):?><div class="bg-rose-500/10 border border-rose-500/30 rounded-lg px-3 py-2 text-rose-400 text-xs text-center mb-4"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="mb-4"><label class="text-xs text-slate-300 uppercase tracking-wider">Contrasena</label><input type="password" name="password" class="w-full bg-slate-700 border border-slate-600 rounded-lg px-3 py-2 text-sm text-slate-200 text-center mt-1 focus:outline-none focus:border-amber-500/50" placeholder="........" required autofocus></div><button type="submit" class="w-full py-2.5 bg-amber-500/20 text-amber-400 border border-amber-500/30 rounded-lg text-sm font-normal hover:bg-amber-500/30 transition">Acceder al Panel</button></form></div></body></html><?php }?>